css:
/* The archive band: intro, the topic chips, the results bar, the grid and the
   pager. Everything that moves is the platform `filter` behaviour on the
   section — the chips are its controls, the cards its items, the count and the
   empty line its readouts. Nothing here is staged or revealed by a script, so
   the band lays out and is editable in the Design canvas, which runs none —
   the component's own js only rewords the count for a single result. */
/* The handoff opens the band at 70px and closes it tight under the pager; the
   panel band below brings its own 80px. Row spacing is stated per row, and at
   the row's own weight, so a later rule here cannot flatten it by accident. */
[data-bz-section="blog-archive"] > .bz-section { padding-block: 70px 20px }
[data-bz-section="blog-archive"] .bz-row[data-bz-node="ba-chips-row"] { margin-top: 0 }
[data-bz-section="blog-archive"] .bz-row[data-bz-node="ba-results-row"] { margin-top: 40px; align-items: baseline }
[data-bz-section="blog-archive"] .bz-row[data-bz-node="ba-grid-row"] { margin-top: 26px }
[data-bz-section="blog-archive"] .bz-row[data-bz-node="ba-pager-row"] { margin-top: 40px }

/* Intro */
[data-bz-section="blog-archive"] [data-bz-node="ba-lead"] .bz-text { max-width: 880px }
[data-bz-section="blog-archive"] [data-bz-node="ba-lead"] p { font-size: 17px; line-height: 1.75; color: var(--ink); margin: 0 0 20px }
[data-bz-section="blog-archive"] [data-bz-node="ba-body"] .bz-text { max-width: 880px }
[data-bz-section="blog-archive"] [data-bz-node="ba-body"] p { font-size: 16px; line-height: 1.75; color: var(--body-text); margin: 0 }

/* Chips. The pills widget draws a scrolling rail for the location finder; a
   topic row wraps instead, and the handoff sets these in sentence case. */
[data-bz-section="blog-archive"] [data-bz-node="ba-chips"] { border-top: 1px solid var(--line); padding-top: 22px; margin-top: 30px }
[data-bz-section="blog-archive"] .ss-filter { gap: 14px }
[data-bz-section="blog-archive"] .ss-filter__pills { flex-wrap: wrap; overflow: visible; padding-bottom: 0; gap: 10px }
[data-bz-section="blog-archive"] .ss-pill {
  padding: 10px 16px; border-width: 1px; border-color: var(--line);
  font: 700 13px/1 var(--font-body); letter-spacing: normal; text-transform: none;
  color: var(--body-text);
}
[data-bz-section="blog-archive"] .ss-pill:hover { border-color: var(--ink); color: var(--ink) }
[data-bz-section="blog-archive"] .ss-pill[aria-pressed="true"] { background: var(--accent); border-color: var(--accent); color: #fff }

/* Results bar: heading and count on one baseline. */
[data-bz-section="blog-archive"] [data-bz-node="ba-h"] h2 { font-size: 30px; line-height: 1.2; margin: 0 }
[data-bz-section="blog-archive"] [data-bz-node="ba-results-count"] { text-align: right }

/* Pager */
[data-bz-section="blog-archive"] [data-bz-node="ba-pager"] .bz-btn { min-height: 46px; padding: 0 24px }

@media (max-width: 640px) {
  [data-bz-section="blog-archive"] > .bz-section { padding-block: 48px 56px }
  [data-bz-section="blog-archive"] [data-bz-node="ba-results-count"] { text-align: left }
  [data-bz-section="blog-archive"] [data-bz-node="ba-h"] h2 { font-size: 26px }
}

js:
/* The one thing the filter behaviour cannot say.
 *
 * Everything that moves on this band is the platform `filter` behaviour: the
 * chips are its controls, the cards its items, the count and the empty line its
 * readouts. Its count is a single template with one hole, so a topic with one
 * post reads "1 articles". This listens to the `bz:filter` event the behaviour
 * already emits and puts the singular wording back — it never filters, hides or
 * stages anything itself, so the band is complete and editable in the Design
 * canvas, which runs no site JS, exactly as it is without this file.
 */
(function () {
  document.querySelectorAll('[data-bz-section="blog-archive"]').forEach(function (band) {
    var count = band.querySelector('[data-bz-part="count"]');
    if (!count) return;
    var many = count.getAttribute('data-bz-count-template') || '';
    var one = count.getAttribute('data-bz-count-one') || '';
    if (!one) return;
    band.addEventListener('bz:filter', function (event) {
      var shown = event.detail && event.detail.shown;
      if (typeof shown !== 'number') return;
      count.textContent = (shown === 1 ? one : many).replace('{n}', String(shown));
    });
  });
})();
